corrected_code:
@router.get("/invoices/lookup")
async def lookup_invoice_by_code(
    invoice_number: str = Query(..., regex=r"^INV-\d{4}-[A-Z0-9]+$"),
    current_user: User = Depends(get_current_user)
):
    invoice = await CustomerInvoice.find_one(
        CustomerInvoice.invoice_number == invoice_number,
        CustomerInvoice.customer_id == current_user.customer_id
    )
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice record not found or access denied")

    return {
        "invoice_id": str(invoice.id),
        "total_amount": invoice.total_amount,
        "currency": invoice.currency,
        "line_items": invoice.items,
        "recipient_tax_id": invoice.tax_id
    }
